/* ============================================================
   WYVERNCHAT THEME — "GILDED SLATE" (art deco / dark slate + gold)
      v2 — remapped onto the real shadcn variable set (card, border,
         accent, etc.) instead of custom variables. FULL REPLACEMENT of
            the Custom CSS block. Do not append to old builds.
               Keyframes used: 1 of 5 (deco-breathe — card idle glow only)
                  ============================================================

                     Set these in the Variables tab first (HSL triplet, no wrapper).
                        If a var(--x) below does nothing once pasted, the real DOM name
                           differs from this guess — inspect and correct (multi-word names
                              are ASSUMED kebab-case, not confirmed):

                                   background              222 18% 8%
                                        foreground              45 25% 90%
                                             card                    220 14% 15%
                                                  cardForeground          45 25% 90%
                                                       popover                 220 14% 15%
                                                            popoverForeground       45 25% 90%
                                                                 primary                 43 70% 54%
                                                                      primaryForeground       222 18% 8%
                                                                           secondary               220 12% 20%
                                                                                secondaryForeground     45 25% 90%
                                                                                     muted                   220 12% 18%
                                                                                          mutedForeground         45 12% 58%
                                                                                               accent                  48 75% 68%
                                                                                                    accentForeground        222 18% 8%
                                                                                                         destructive             6 60% 46%
                                                                                                              destructiveForeground   45 25% 90%
                                                                                                                   border                  43 40% 38%
                                                                                                                        input                   220 12% 20%
                                                                                                                             ring                    48 75% 68%

                                                                                                                                  sidebarBackground           222 20% 6%
                                                                                                                                       sidebarForeground           45 20% 85%
                                                                                                                                            sidebarPrimary              43 70% 54%
                                                                                                                                                 sidebarPrimaryForeground    222 18% 8%
                                                                                                                                                      sidebarAccent               220 12% 14%
                                                                                                                                                           sidebarAccentForeground     45 25% 90%
                                                                                                                                                                sidebarBorder               43 40% 38%
                                                                                                                                                                     sidebarRing                 48 75% 68%
                                                                                                                                                                        ============================================================ */

                                                                                                                                                                        /* ---------- PAGE CANVAS ---------- */
                                                                                                                                                                        body {
                                                                                                                                                                          background-color: hsl(var(--background)) !important;
                                                                                                                                                                            background-image:
                                                                                                                                                                                repeating-linear-gradient(45deg,  hsl(var(--border) / 0.035) 0px, hsl(var(--border) / 0.035) 2px, transparent 2px, transparent 40px),
                                                                                                                                                                                    repeating-linear-gradient(-45deg, hsl(var(--border) / 0.035) 0px, hsl(var(--border) / 0.035) 2px, transparent 2px, transparent 40px) !important;
                                                                                                                                                                                      background-attachment: fixed !important;
                                                                                                                                                                                      }

                                                                                                                                                                                      /* ---------- CARD (solid slate, concentric frame, breathing glow) ---------- */
                                                                                                                                                                                      .message-container {
                                                                                                                                                                                        position: relative !important;
                                                                                                                                                                                          overflow: visible !important;
                                                                                                                                                                                            background-color: hsl(var(--card)) !important;
                                                                                                                                                                                              background-image: none !important;
                                                                                                                                                                                                border: none !important;
                                                                                                                                                                                                  border-radius: 0 !important;
                                                                                                                                                                                                    padding: 18px 16px 14px 16px !important;
                                                                                                                                                                                                      margin-top: 22px !important;
                                                                                                                                                                                                        animation: deco-breathe 5s ease-in-out infinite !important;
                                                                                                                                                                                                        }

                                                                                                                                                                                                        @keyframes deco-breathe {
                                                                                                                                                                                                          0%, 100% {
                                                                                                                                                                                                              box-shadow:
                                                                                                                                                                                                                    0 0 0 1px hsl(var(--border)),
                                                                                                                                                                                                                          0 0 0 4px hsl(var(--card)),
                                                                                                                                                                                                                                0 0 0 5px hsl(var(--border) / 0.6),
                                                                                                                                                                                                                                      0 0 14px 2px hsl(var(--accent) / 0.12);
                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                          50% {
                                                                                                                                                                                                                                              box-shadow:
                                                                                                                                                                                                                                                    0 0 0 1px hsl(var(--border)),
                                                                                                                                                                                                                                                          0 0 0 4px hsl(var(--card)),
                                                                                                                                                                                                                                                                0 0 0 5px hsl(var(--border) / 0.6),
                                                                                                                                                                                                                                                                      0 0 22px 4px hsl(var(--accent) / 0.28);
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        .user-message { border-color: hsl(var(--accent)) !important; }
                                                                                                                                                                                                                                                                        .ai-message   { border-color: hsl(var(--border)) !important; }

                                                                                                                                                                                                                                                                        .message-body,
                                                                                                                                                                                                                                                                        .message-content-wrapper {
                                                                                                                                                                                                                                                                          position: static !important;
                                                                                                                                                                                                                                                                            min-width: 0 !important;
                                                                                                                                                                                                                                                                              overflow-wrap: break-word !important;
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                              /* ---------- AVATAR: left, sepia, dissolves into the slate ---------- */
                                                                                                                                                                                                                                                                              .message-avatar {
                                                                                                                                                                                                                                                                                margin-right: 14px !important;
                                                                                                                                                                                                                                                                                  border-left: 3px solid hsl(var(--primary)) !important;
                                                                                                                                                                                                                                                                                    background-color: hsl(var(--card)) !important;
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                    .avatar-image,
                                                                                                                                                                                                                                                                                    .avatar-image-persona,
                                                                                                                                                                                                                                                                                    .avatar-image-character,
                                                                                                                                                                                                                                                                                    .avatar-image-npc {
                                                                                                                                                                                                                                                                                      filter: sepia(0.55) contrast(1.08) brightness(0.92) !important;
                                                                                                                                                                                                                                                                                        box-shadow:
                                                                                                                                                                                                                                                                                            inset -24px 0 20px -6px hsl(var(--card)),
                                                                                                                                                                                                                                                                                                inset 0 0 18px 3px hsl(var(--card) / 0.4) !important;
                                                                                                                                                                                                                                                                                                  transition: filter 0.5s ease !important;
                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                  .message-container:hover .avatar-image,
                                                                                                                                                                                                                                                                                                  .message-container:hover .avatar-image-persona,
                                                                                                                                                                                                                                                                                                  .message-container:hover .avatar-image-character,
                                                                                                                                                                                                                                                                                                  .message-container:hover .avatar-image-npc {
                                                                                                                                                                                                                                                                                                    filter: sepia(0) contrast(1) brightness(1) !important;
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                    /* ---------- NAMEPLATE: skewed gold badge overlapping the top edge ---------- */
                                                                                                                                                                                                                                                                                                    .message-username {
                                                                                                                                                                                                                                                                                                      position: absolute !important;
                                                                                                                                                                                                                                                                                                        top: -13px;
                                                                                                                                                                                                                                                                                                          left: 14px;
                                                                                                                                                                                                                                                                                                            z-index: 2;
                                                                                                                                                                                                                                                                                                              background-image: linear-gradient(135deg, hsl(var(--primary)), hsl(var(--accent)), hsl(var(--primary)));
                                                                                                                                                                                                                                                                                                                color: hsl(var(--primary-foreground));
                                                                                                                                                                                                                                                                                                                  font-family: "Cinzel", Georgia, serif;
                                                                                                                                                                                                                                                                                                                    font-weight: 700;
                                                                                                                                                                                                                                                                                                                      letter-spacing: 0.1em;
                                                                                                                                                                                                                                                                                                                        text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                          padding: 3px 16px;
                                                                                                                                                                                                                                                                                                                            transform: skewX(-12deg);
                                                                                                                                                                                                                                                                                                                              box-shadow: 2px 2px 0 hsl(var(--background));
                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                              .message-index { display: none !important; }

                                                                                                                                                                                                                                                                                                                              /* ---------- TIMESTAMP: small skewed placard, bottom-right ---------- */
                                                                                                                                                                                                                                                                                                                              .message-timestamp {
                                                                                                                                                                                                                                                                                                                                position: absolute !important;
                                                                                                                                                                                                                                                                                                                                  bottom: 6px;
                                                                                                                                                                                                                                                                                                                                    right: 12px;
                                                                                                                                                                                                                                                                                                                                      background-color: hsl(var(--border) / 0.22);
                                                                                                                                                                                                                                                                                                                                        border: 1px solid hsl(var(--border));
                                                                                                                                                                                                                                                                                                                                          color: hsl(var(--accent));
                                                                                                                                                                                                                                                                                                                                            font-family: "Oswald", Arial, sans-serif;
                                                                                                                                                                                                                                                                                                                                              letter-spacing: 0.04em;
                                                                                                                                                                                                                                                                                                                                                font-size: 11px;
                                                                                                                                                                                                                                                                                                                                                  padding: 1px 10px;
                                                                                                                                                                                                                                                                                                                                                    transform: skewX(-12deg);
                                                                                                                                                                                                                                                                                                                                                      pointer-events: none;
                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                      /* ---------- PROSE ---------- */
                                                                                                                                                                                                                                                                                                                                                      .message-content {
                                                                                                                                                                                                                                                                                                                                                        font-family: "Cormorant Garamond", Georgia, "Times New Roman", serif;
                                                                                                                                                                                                                                                                                                                                                          color: hsl(var(--card-foreground));
                                                                                                                                                                                                                                                                                                                                                            line-height: 1.75;
                                                                                                                                                                                                                                                                                                                                                              letter-spacing: 0.01em;
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                              .quote-text {
                                                                                                                                                                                                                                                                                                                                                                color: hsl(var(--accent));
                                                                                                                                                                                                                                                                                                                                                                  font-style: italic;
                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                  .entry-highlight {
                                                                                                                                                                                                                                                                                                                                                                    background-color: hsl(var(--card)) !important;
                                                                                                                                                                                                                                                                                                                                                                      background-image: linear-gradient(120deg,
                                                                                                                                                                                                                                                                                                                                                                          hsl(var(--border) / 0.35),
                                                                                                                                                                                                                                                                                                                                                                              hsl(var(--accent) / 0.55),
                                                                                                                                                                                                                                                                                                                                                                                  hsl(var(--border) / 0.35)) !important;
                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid hsl(var(--border));
                                                                                                                                                                                                                                                                                                                                                                                      color: hsl(var(--background));
                                                                                                                                                                                                                                                                                                                                                                                        padding: 0 4px;
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                        /* ---------- ACTIONS / SWIPE ---------- */
                                                                                                                                                                                                                                                                                                                                                                                        .message-actions .btn-icon {
                                                                                                                                                                                                                                                                                                                                                                                          color: hsl(var(--accent)) !important;
                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                          .message-swipe-controls {
                                                                                                                                                                                                                                                                                                                                                                                            color: hsl(var(--border)) !important;
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                            /* ---------- INPUT BAR ---------- */
                                                                                                                                                                                                                                                                                                                                                                                            .chat-input-bar {
                                                                                                                                                                                                                                                                                                                                                                                              background-color: hsl(var(--card)) !important;
                                                                                                                                                                                                                                                                                                                                                                                                border: 1px solid hsl(var(--border)) !important;
                                                                                                                                                                                                                                                                                                                                                                                                  box-shadow:
                                                                                                                                                                                                                                                                                                                                                                                                      0 0 0 1px hsl(var(--border) / 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                          0 0 12px hsl(var(--accent) / 0.15) !important;
                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                          .chat-send-icon,
                                                                                                                                                                                                                                                                                                                                                                                                          .chat-arrow-icon {
                                                                                                                                                                                                                                                                                                                                                                                                            color: hsl(var(--accent)) !important;
                                                                                                                                                                                                                                                                                                                                                                                                            }

